async () => {
  const checks = [], pause = () => new Promise(r => setTimeout(r, 20));
  const assert = (name, value) => { if (!value) throw Error(name); checks.push(name); };
  async function until(test) { for (let n=0;n<100;n++) { if(test()) return; await pause(); } throw Error("UI_WAIT_TIMEOUT"); }
  await until(() => !!globalThis.__ownedFixture);
  if(document.querySelector('#workspace-tour')?.open) document.querySelector('#tour-skip').click();
  await __preview.ui.activate({load:false});
  document.querySelector('[data-page=compare]').click();
  const get = id => document.getElementById(id), state = __ownedPreview;
  function draft(){ get('compare-question').value=__ownedFixture.run.request.original_question; for(const n of document.querySelectorAll('#compare-methods input')) n.checked=['bm25','vector','hybrid'].includes(n.value); }
  draft(); const before = state.posts.length;
  get('compare-form').requestSubmit(); await until(()=>state.posts.length===before+1);
  await pause(); await __preview.ui.compare.refresh(); await until(()=>document.querySelectorAll('.compare-result ol').length===3);
  assert('explicit intent submits exactly once for three methods',state.posts.length===before+1);
  assert('three recorded retrieval result cards render',document.querySelectorAll('.compare-result').length===3);
  assert('no page horizontal overflow',document.documentElement.scrollWidth<=innerWidth);
  assert('mobile exposes one selected method',innerWidth>700||[...document.querySelectorAll('.compare-result')].filter(n=>getComputedStyle(n).display!=='none').length===1);
  get('compare-progress').querySelector('[data-method=hybrid]').click();
  assert('method selector changes selected panel',document.querySelector('.compare-result[data-selected=true] h3').textContent==='Hybrid');
  document.querySelector('.compare-result[data-selected=true] li button').click();
  await until(()=>!!get('compare-source').querySelector('blockquote'));
  assert('saved source passage has an official AWS link',get('compare-source').querySelector('a').hostname==='docs.aws.amazon.com');
  state.delaySource=true; const sourceButtons=[...document.querySelectorAll('.compare-result[data-selected=true] li button')];
  sourceButtons[0].click();sourceButtons[1].click();await until(()=>state.sourceResolvers.length===2);
  assert('new source clears old passage while loading',!get('compare-source').querySelector('blockquote'));
  state.sourceResolvers[1]();await pause();const second=get('compare-source').querySelector('blockquote').textContent;
  state.sourceResolvers[0]();await pause();state.delaySource=false;state.sourceResolvers=[];
  assert('late source A cannot replace newer source B',get('compare-source').querySelector('blockquote').textContent===second);
  const original=__preview.overrides.runs;
  __preview.overrides.runs=async(path,options)=>{if(path.includes('/sources/'))throw Object.assign(Error('synthetic source missing'),{status:404});return original(path,options);};
  sourceButtons[0].click();await until(()=>get('compare-source').textContent.includes('unavailable'));
  assert('failed source clears previous evidence',!get('compare-source').querySelector('blockquote'));
  __preview.overrides.runs=original;
  get('compare-trace-open').click();await until(()=>!!get('compare-trace').querySelector('pre'));
  assert('saved trace is retrieval-only and ungraded',JSON.parse(get('compare-trace').textContent).quality_metrics===null);
  __preview.realDownload=false;const exports=__preview.downloads.length,reads=state.reads;
  get('compare-export').click();await until(()=>__preview.downloads.length===exports+1);
  const exported=JSON.parse(__preview.downloads.at(-1).text);
  assert('JSON export reauthorizes detail before download',state.reads>reads&&exported.results.length===3&&exported.quality_metrics===null);
  assert('source trace export and refresh never submit another job',state.posts.length===before+1);
  state.ambiguous=true;draft();get('compare-form').requestSubmit();
  await until(()=>get('compare-status').textContent.includes('could not be confirmed'));await pause();
  const lost=state.posts.at(-1);assert('ambiguous submit exposes manual recovery only',!get('compare-recover').hidden&&get('compare-submit').disabled&&state.posts.length===before+2);
  get('compare-question').value='Changed text must not change recovery intent';get('compare-recover').click();
  await until(()=>state.posts.length===before+3);await pause();
  assert('manual recovery preserves original idempotency key and frozen payload',state.posts.at(-1).key===lost.key&&JSON.stringify(state.posts.at(-1).body)===JSON.stringify(lost.body));
  state.hold=true;draft();get('compare-form').requestSubmit();await until(()=>state.posts.length===before+4);await pause();
  assert('queued work exposes cancellation',!get('compare-cancel').disabled);
  get('compare-cancel').click();await until(()=>get('compare-run-meta').textContent.startsWith('CANCELLED'));
  assert('terminal cancellation disables further cancellation',get('compare-cancel').disabled);state.hold=false;
  draft();get('compare-form').requestSubmit();await until(()=>state.posts.length===before+5);await pause();
  await __preview.ui.compare.refresh();await until(()=>!get('compare-export').disabled);
  const count=__preview.downloads.length;state.authError=true;get('compare-export').click();await pause();await pause();
  assert('revoked export never downloads a cached result',__preview.downloads.length===count);
  assert('authorization failure clears entire workspace and private question',get('workspace').hidden&&get('compare-source').textContent===''&&get('compare-history').textContent===''&&get('compare-question').value==='');
  state.authError=false;await __preview.ui.activate({load:false});
  assert('fresh session restores no previous private run',get('compare-results').textContent===''&&get('compare-question').value==='');
  return {status:'PASS_LOCAL_COMPARE_BROWSER',checks,checked_at:new Date().toISOString(),viewport:innerWidth,model_calls:0,aws_calls:0,scope:'Production UI, recorded public retrieval, simulated account/queue/status. Not managed AWS integration or answer-quality evidence.'};
}
